WITH metrics_long AS (SELECT * FROM (SELECT id, supplier_id, price, cost FROM products) src UNPIVOT (reading FOR measure IN (price, cost))) SELECT measure, CASE WHEN reading >= 61 THEN 'LARGE' ELSE 'SMALL' END AS reading_tier, PERCENTILE_APPROX(reading, 0.9) AS reading_p90, COUNT(CASE WHEN measure = 'price' THEN 1 END) AS price_count FROM metrics_long GROUP BY CUBE (measure, CASE WHEN reading >= 61 THEN 'LARGE' ELSE 'SMALL' END) ORDER BY reading_p90 DESC NULLS FIRST;
